function renderGame(){
  const c=state.character, s=state.stats;
  $('#app').innerHTML=`<div class="shell">
    <aside class="sidebar"><div class="brand"><span class="brand-mark">E</span><span>EVERLIFE</span></div><nav class="nav">
      <div class="nav-label">My life</div>${navButton('dashboard','⌂','Today')}${navButton('activities','✦','Activities')}${navButton('career','▥','Career')}${navButton('school','⌁','School')}${navButton('relationships','♧','People')}
      <div class="nav-label">World</div>${navButton('map','◎','World map')}${navButton('venues','◇','City venues')}${navButton('market','◫','Infinity market')}${navButton('garage','▰','Garage')}
      <div class="nav-label">Personal</div>${navButton('phone','▯','My phone')}${navButton('achievements','♛','Milestones')}${state.admin?navButton('admin','⚡','Admin panel'):''}
      </nav><div class="sidebar-foot"><div class="sync-pill"><span class="dot" style="background:${state.archive.connected?'var(--mint)':'var(--gold)'}"></span>${state.archive.connected?'Sheets archive connected':'Archive stored locally'}</div></div></aside>
    <header class="topbar"><div class="identity"><div class="avatar">${esc(c.first[0]+c.last[0])}</div><div><div class="id-name">${esc(c.name)}</div><div class="id-meta">${c.flag||''} Age ${c.age} · ${esc(c.city)}, ${esc(c.country)}</div></div></div><div class="wallet"><div class="wallet-item"><b>$${fmt(state.money)}</b><small>${esc(c.currency||'USD')} available funds</small></div><div class="wallet-item"><b>◆ ${fmt(state.points)}</b><small>Life points</small></div><button class="top-icon" data-open="achievements">♧<i></i></button></div></header>
    <main class="main">${dashboardHTML()}</main><aside class="rightbar">${rightbarHTML()}</aside></div>`;
  bindOpeners();
}
function navButton(id,icon,label){ return `<button class="${id==='dashboard'?'active':''}" ${id==='dashboard'?'data-dashboard':'data-open="'+id+'"'}><span>${icon}</span><b>${label}</b></button>`; }
function dashboardHTML(){
  const recent=state.events.slice(0,6); const c=state.character;
  return `<div class="section-title"><div><div class="eyebrow">${monthName(state.calendar.month)} ${state.calendar.day}, ${state.calendar.year}</div><h2>Your life, today</h2></div><p>${state.alive?'Every choice writes the next line.':'This life has ended.'}</p></div>
  <section class="hero"><div class="weather">☀ 24°C<br><span class="muted">Clear skies · ${esc(c.city)}</span></div><div class="hero-tag">Chapter ${Math.max(1,c.age-17)} · Becoming</div><h1>${greeting()}, ${esc(c.first)}.</h1><p>${storyPrompt()}</p></section>
  <div class="quick-grid"><button class="quick" data-open="activities"><i>✦</i><b>Choose an activity</b><small>Grow your skills</small></button><button class="quick" data-open="career"><i>▥</i><b>${state.career.salary?'Go to work':'Find a career'}</b><small>${esc(state.career.title)}</small></button><button class="quick" data-open="map"><i>◎</i><b>Explore the world</b><small>${state.visited.length} cities discovered</small></button><button class="quick" data-open="phone"><i>▯</i><b>Open your phone</b><small>${state.phone.battery}% battery</small></button></div>
  <section class="life-card"><div class="card-head"><h3>Life timeline</h3><button class="ghost" data-open="sheets">Google Sheets archive</button></div><div class="feed">${recent.map((e,i)=>`<div class="feed-item"><div class="feed-date">${esc(e.date)}</div><div class="feed-line"><i style="background:${e.major?'var(--gold)':'var(--mint)'}"></i></div><div class="feed-copy"><b>${esc(e.title)}</b><p>${esc(e.text)}</p></div></div>`).join('')}</div></section>`;
}
function rightbarHTML(){
  const s=state.stats,c=state.character;
  return `<div class="right-head"><div><div class="eyebrow">Live condition</div><h3>Vitals</h3></div><span class="dot"></span></div><div class="vitals">${vital('Health',s.health,'#70f0be')}${vital('Happiness',s.happiness,'#f2c66d')}${vital('Smarts',s.smarts,'#73aaf8')}${vital('Hunger',s.hunger,'#ff805f')}${vital('Social',s.social,'#b894fa')}</div><div class="divider"></div>
  <div class="eyebrow">Current chapter</div><div class="profile-list" style="margin-top:15px"><div class="profile-row"><span>Occupation</span><b>${esc(state.career.title)}</b></div><div class="profile-row"><span>Education</span><b>${esc(state.education.name)}</b></div><div class="profile-row"><span>Home</span><b>${esc(c.city)}</b></div><div class="profile-row"><span>Net worth</span><b>$${fmt(state.money)}</b></div></div><div class="trait-wrap">${c.traits.map(x=>`<span class="tag">${x}</span>`).join('')}</div>
  <div class="time-controls"><button class="time-btn secondary" data-time="day">Pass a day</button><button class="time-btn" data-time="month">Pass a month →</button></div>`;
}
function vital(name,val,color){return `<div><div class="vital-top"><span>${name}</span><b>${Math.round(val)}%</b></div><div class="bar"><i style="width:${clamp(val)}%;background:${color}"></i></div></div>`;}
function monthName(n){return ['','January','February','March','April','May','June','July','August','September','October','November','December'][n];}
function greeting(){ const h=new Date().getHours(); return h<12?'Good morning':h<18?'Good afternoon':'Good evening'; }
function storyPrompt(){
  if(state.stats.hunger<25) return 'Hunger is beginning to shape every decision. Find food before the next chapter moves on.';
  if(state.stats.health<30) return 'Your body is asking for care. Rest, eat well, or visit the spa before pushing further.';
  if(!state.career.salary) return 'You have a small apartment, a full city outside, and enough money to choose your first direction.';
  return `Life is moving in ${state.character.city}. Your work as ${state.career.title} is building momentum, but the day is still yours.`;
}

function bindOpeners(){
  $$('[data-open]').forEach(b=>b.onclick=()=>openModal(b.dataset.open));
  $$('[data-time]').forEach(b=>b.onclick=()=>passTime(b.dataset.time));
}
function openModal(kind,tab=null){ currentModal=kind; modalTab=tab; document.body.insertAdjacentHTML('beforeend',modalShell(kind)); bindModal(kind); }
function rerenderModal(){ const old=$('.modal-layer'); if(old) old.remove(); if(currentModal) openModal(currentModal,modalTab); }
function closeModal(){ $('.modal-layer')?.remove(); currentModal=null; modalTab=null; renderGame(); }
function modalShell(kind){ const meta=modalMeta(kind); return `<div class="modal-layer"><section class="modal ${meta.full?'full':''}"><header class="modal-head"><div><div class="eyebrow">${meta.eyebrow}</div><h2>${meta.title}</h2></div><button class="close ${meta.full?'red':''}" data-close>×</button></header><div class="modal-body">${modalContent(kind)}</div></section></div>`; }
function modalMeta(kind){ return ({activities:['Build your days','Activities'],career:['The world of work','Career studio'],school:['Learn & connect','Campus'],relationships:['Your people','Relationships & family'],map:['Explore without limits','World map',true],venues:['Your city, alive','City venues'],market:['Procedurally stocked','Infinity market'],garage:['Movement & freedom','My garage'],phone:['Samsung A57 5G · 250GB','My phone'],achievements:['The moments that remain','Life milestones'],admin:['Unlocked with admin123','Admin panel'],sheets:['Automatic event archive','Google Sheets'],settings:['Control your experience','Settings']})[kind]?.reduce((o,v,i)=>({...o,[['eyebrow','title','full'][i]]:v}),{})||{eyebrow:'Everlife',title:'Life',full:false}; }
function modalContent(kind){ return ({activities:activitiesHTML,career:careerHTML,school:schoolHTML,relationships:relationshipsHTML,map:mapHTML,venues:venuesHTML,market:marketHTML,garage:garageHTML,phone:phoneHTML,achievements:achievementsHTML,admin:adminHTML,sheets:sheetsHTML,settings:settingsHTML}[kind]||(()=>''))(); }

function activitiesHTML(){ const active=modalTab||'Home'; return `<div class="toolbar"><div class="tabs">${Object.keys(ACTIVITY_GROUPS).map(k=>`<button class="tab ${active===k?'active':''}" data-tab="${k}">${k}</button>`).join('')}</div></div><div class="content-grid">${ACTIVITY_GROUPS[active].map((a,i)=>activityCard(a,active,i)).join('')}</div>`; }
function activityCard(a,g,i){return `<article class="item-card"><div class="item-icon">${a[1]}</div><h3>${a[0]}</h3><p>${effectText(a[3])}</p><div class="item-bottom"><span class="price">${a[2]?'$'+a[2]:'Free'}</span><button class="tiny-btn" data-activity="${g}|${i}">Do it</button></div></article>`;}
function effectText(e){return Object.entries(e).map(([k,v])=>`${v>0?'+':''}${v} ${k.replace('careerXp','career XP')}`).join(' · ');}

function careerHTML(){
  const tier=Number(modalTab??0), cfg=CAREER_LEVELS[tier];
  return `<div class="sheet-banner"><div class="eyebrow">Current position</div><h3>${esc(state.career.title)}</h3><div class="muted">${state.career.salary?'$'+fmt(state.career.salary)+' / month · '+state.career.xp+' XP':'Choose a field and earn your first opportunity.'}</div>${state.career.salary?'<button class="primary" style="margin-top:13px" data-work>Work this month</button>':''}</div>
  <div class="toolbar"><div class="tabs">${CAREER_LEVELS.map((x,i)=>`<button class="tab ${i===tier?'active':''}" data-tab="${i}">${i+1}. ${x.name}</button>`).join('')}</div><span class="micro">125 career paths across five tiers</span></div>
  <div class="content-grid">${CAREER_SECTORS.map((sector,i)=>{ const eligible=state.character.age>=cfg.age&&state.stats.smarts>=cfg.smarts&&state.education.level>=cfg.edu; return `<article class="item-card"><div class="item-icon">${careerIcon(sector)}</div><h3>${cfg.prefix} ${sector}</h3><p>$${fmt(cfg.salary+(i*17))}/month · Requires age ${cfg.age}, ${cfg.smarts} smarts, education level ${cfg.edu}</p><div class="item-bottom"><span class="price">Tier ${tier+1}</span><button class="tiny-btn" ${eligible?'':'disabled'} data-job="${tier}|${i}">${eligible?'Apply':'Locked'}</button></div></article>`;}).join('')}</div>`;
}
function careerIcon(s){ return ({Software:'💻',Medicine:'🩺',Law:'⚖️',Education:'🎓',Design:'✒️',Film:'🎬',Music:'🎧',Finance:'📊',Space:'🛰️',Culinary:'🍽️',Sports:'🏆',Gaming:'🎮',Aviation:'✈️'}[s]||'◈'); }

function schoolHTML(){
  return `<div class="two-pane"><section class="panel"><div class="eyebrow">Academic record</div><h3>${esc(state.education.name)}</h3>${vital('Average grade',state.education.grade,'var(--blue)')}${vital('Smarts',state.stats.smarts,'var(--mint)')}<button class="primary wide" data-study>Attend a class</button><button class="ghost" style="width:100%;margin-top:8px" data-test>Take 5-question exam</button></section><section><div class="card-head"><h3>Your classmates</h3><span class="micro">Memories change with every interaction</span></div><div class="content-grid">${state.classmates.map(p=>`<article class="item-card"><div class="item-icon">${p.name.split(' ').map(x=>x[0]).join('')}</div><h3>${esc(p.name)}</h3><p>${p.mood} · Friendship ${p.friendship}%<br>${esc(p.memory)}</p><div class="item-bottom"><button class="tiny-btn" data-classmate="${p.id}|talk">Talk</button><button class="tiny-btn" data-classmate="${p.id}|study">Study together</button></div></article>`).join('')}</div></section></div>`;
}

function relationshipsHTML(){
  const parents=state.relationships.filter(r=>['Mother','Father','Parent'].includes(r.role)); const others=state.relationships.filter(r=>!['Mother','Father','Parent'].includes(r.role));
  return `<div class="toolbar"><button class="tab ${modalTab!=='list'?'active':''}" data-tab="tree">Family tree</button><button class="tab ${modalTab==='list'?'active':''}" data-tab="list">People</button><button class="ghost" data-meet>Meet someone new</button></div>${modalTab==='list'?`<div class="content-grid">${state.relationships.map(personCard).join('')}</div>`:`<div class="panel" style="overflow:auto"><div class="tree"><div class="tree-row">${parents.map(treeNode).join('')}</div><div class="tree-row">${treeNode({name:state.character.name,role:'You',age:state.character.age,emoji:state.character.first[0]})}</div><div class="tree-row">${others.map(treeNode).join('')}</div></div></div>`}`;
}
function treeNode(r){return `<div class="tree-node"><div class="tree-avatar">${esc(r.emoji||r.name[0])}</div><b>${esc(r.name)}</b><br><small>${r.role} · Age ${r.age}</small></div>`;}
function personCard(r){return `<article class="item-card"><div class="item-icon">${esc(r.emoji||r.name[0])}</div><h3>${esc(r.name)}</h3><p>${r.role} · Age ${r.age}<br>Bond: ${r.bond}%</p><div class="item-bottom"><button class="tiny-btn" data-person="${r.id}|call">Call</button><button class="tiny-btn" data-person="${r.id}|gift">Send gift · $25</button></div></article>`;}

function mapHTML(){
  return `<div class="world-map"><div class="map-overlay"><div class="eyebrow">Current location</div><h3>${esc(state.character.city)}</h3><p class="muted" style="font-size:11px;line-height:1.5">Choose a pin to travel. Your save stays active everywhere you go.</p><div class="field" style="margin:13px 0 0"><input id="mapSearch" placeholder="Search a city or country…" /></div><div id="mapResult" class="micro">${state.visited.length} cities in your travel history</div></div>${MAP_CITIES.map((c,i)=>`<button class="pin" style="left:${c.x}%;top:${c.y}%" data-city="${i}" title="${c.name}"><span>${c.emoji}</span></button>`).join('')}</div>`;
}

function venuesHTML(){ const selected=modalTab||'Library',v=VENUES[selected]; return `<div class="two-pane"><aside class="panel venue-nav">${Object.entries(VENUES).map(([k,x])=>`<button class="${k===selected?'active':''}" data-tab="${k}">${x.icon} &nbsp;${k}</button>`).join('')}</aside><section class="panel"><div class="eyebrow">${v.icon} ${esc(state.character.city)}</div><h3 style="font-size:34px;margin-top:7px">${selected}</h3><p class="muted">${v.blurb}</p><div class="content-grid" style="margin-top:24px">${v.actions.map((a,i)=>activityCard([a[0],v.icon,a[1],a[2]],`venue:${selected}`,i)).join('')}</div></section></div>`; }

function marketHTML(){ const category=modalTab||'Food'; return `<div class="toolbar"><div class="tabs">${Object.keys(MARKET).map(k=>`<button class="tab ${k===category?'active':''}" data-tab="${k}">${MARKET_ICONS[k]} ${k}</button>`).join('')}</div><span class="micro">Stock seed #${state.character.age*1000000+state.calendar.month} · fresh stock every age-up</span></div><div class="content-grid" id="marketGrid">${marketItems(category,0,24)}</div><button class="ghost wide" style="margin-top:15px" data-load-market>Generate 24 more items</button>`; }
function marketItems(category,start,count){ return Array.from({length:count},(_,n)=>{ const i=start+n, base=MARKET[category][i%MARKET[category].length], edition=['Classic','Studio','Nova','Heritage','Ultra','Local','Apex'][Math.floor(i/MARKET[category].length)%7]; const price=priceFor(category,i); return `<article class="item-card"><div class="item-icon">${MARKET_ICONS[category]}</div><h3>${edition} ${base} #${String(i+1).padStart(3,'0')}</h3><p>${marketDesc(category)} · Condition: new · Edition ${Math.floor(i/7)+1}</p><div class="item-bottom"><span class="price">$${fmt(price)}</span><button class="tiny-btn" data-buy="${category}|${i}|${price}">Buy</button></div></article>`; }).join(''); }
function priceFor(cat,i){ const base={Food:4,Apparel:35,Tech:260,Home:35000,Vehicles:8000,Future:2500000}[cat]; return Math.round(base*(1+(i%12)*.27)); }
function marketDesc(cat){return ({Food:'Restores hunger',Apparel:'Boosts confidence',Tech:'Unlocks digital possibilities',Home:'Builds long-term comfort',Vehicles:'Adds to your garage',Future:'A rare endgame asset'})[cat];}

function garageHTML(){ return state.vehicles.length?`<div class="content-grid">${state.vehicles.map((v,i)=>`<article class="item-card"><div class="item-icon">🚘</div><h3>${esc(v.name)}</h3><p>Condition ${v.condition}% · ${v.distance} km driven</p><div class="item-bottom"><button class="tiny-btn" data-car="${i}|drive">Take a drive</button><button class="tiny-btn" data-car="${i}|clean">Clean · $20</button><button class="tiny-btn" data-car="${i}|sell">Sell</button></div></article>`).join('')}</div>`:`<div class="empty">Your garage is waiting.<br><button class="primary" style="margin-top:15px" data-jump-market="Vehicles">Browse vehicles</button></div>`; }

function phoneHTML(){ return `<div class="phone-wrap"><div class="phone"><div class="screen"><div class="phone-status"><b>${String(new Date().getHours()).padStart(2,'0')}:${String(new Date().getMinutes()).padStart(2,'0')}</b><span>5G ▰ ${state.phone.battery}%</span></div><div class="phone-hello"><span class="micro">${monthName(state.calendar.month)} ${state.calendar.day}</span><b>Hello, ${esc(state.character.first)}</b></div><div class="phone-apps">${phoneApp('Messages','💬','#56b673','#1f7049')}${phoneApp('Life Map','🗺️','#73aaf8','#395ba1','map')}${phoneApp('My Bank','💳','#242b36','#10151c')}${phoneApp('Camera','📷','#a5aeb2','#455054')}${phoneApp('Chat MTP','✦','#b894fa','#673ba1')}${phoneApp('Play Store','🎮','#ff805f','#9a3c2b')}${phoneApp('Dating','♥','#fa7196','#a42e53')}${phoneApp('Settings','⚙️','#75847e','#34443e','settings')}${phoneApp('Sheets','▦','#58b77c','#276241','sheets')}${phoneApp('Gallery','🌄','#f2c66d','#9b6f2d')}${phoneApp('Calendar','17','#e85c5c','#8f2626')}${phoneApp('Health','♡','#f6f6f6','#929292')}</div><div class="phone-home"></div></div></div><section class="phone-detail"><div class="eyebrow">Starter device</div><h2>Life in your pocket.</h2><p>Your Samsung A57 5G keeps the systems around your life connected. Apps consume fictional storage and battery; upgrades unlock themes and capacity.</p><div class="panel" style="margin-top:25px"><div class="setting-row"><span>Storage used</span><b>${state.phone.storage} / 250 GB</b></div><div class="setting-row"><span>Battery health</span><b>100%</b></div><div class="setting-row"><span>Network</span><b>EverNet 5G</b></div><div class="setting-row"><span>OS</span><b>LifeOS 1.0</b></div></div></section></div>`; }
function phoneApp(name,icon,a,b,open=''){return `<button class="app-icon" ${open?`data-phone-open="${open}"`:`data-phone-app="${name}"`}><i style="--a:${a};--b:${b}">${icon}</i>${name}</button>`;}

function achievementsHTML(){ const all=[['First Breath','Begin a new life','🌱'],['First Paycheque','Earn money from a career','💼'],['World Citizen','Visit three cities','🌍'],['Deep Thinker','Reach 90 smarts','🧠'],['Found Family','Build five relationships','♥'],['Billionaire','Hold one billion dollars','♛'],['Century','Reach age 100','∞'],['Collector','Own ten items','◫']]; return `<div class="panel">${all.map(a=>`<div class="achievement ${state.achievements.includes(a[0])?'':'locked'}"><i>${a[2]}</i><div><b>${a[0]}</b><p>${a[1]} ${state.achievements.includes(a[0])?'· Unlocked':'· Locked'}</p></div></div>`).join('')}</div>`; }

function settingsHTML(){return `<div class="two-pane"><aside class="panel venue-nav"><button class="active">◉ Profile</button><button>◈ Network & internet</button><button>♫ Sound & vibration</button><button>☼ Display</button><button>▦ Storage</button><button>⌁ Security & privacy</button><button>◎ Location</button></aside><section class="panel"><div class="eyebrow">Samsung A57 5G</div><h3>Phone settings</h3>${settingRow('Wi-Fi',state.settings.wifi,'wifi')}${settingRow('Game sounds',state.settings.sound,'sound')}${settingRow('Dark display',state.settings.dark,'dark')}<div class="setting-row"><span>Storage</span><b>${state.phone.storage}GB / 250GB</b></div><div class="setting-row"><span>Phone condition</span><b>Excellent</b></div><div class="divider"></div><div class="eyebrow">Redeem a code</div><div class="code-box" style="margin-top:10px"><input class="search" id="redeemInput" placeholder="Enter code" /><button class="primary" data-redeem>Redeem</button></div><button class="ghost" style="margin-top:35px;color:var(--danger)" data-new-life>Start a new life</button></section></div>`;}
function settingRow(name,on,key){return `<div class="setting-row"><span>${name}</span><span class="switch ${on?'on':''}" data-setting="${key}"><i></i></span></div>`;}

function sheetsHTML(){ const a=state.archive; return `<div class="sheet-banner"><div class="eyebrow">Life Archive</div><h3>${a.connected?'Automatic sync is on':'Connect one Google account for every character'}</h3><p class="muted" style="font-size:11px;line-height:1.55">Everlife can send each major event and career milestone to a Google Apps Script web endpoint you control. Your Gmail address is saved locally as the archive owner.</p></div><div class="two-pane"><section class="panel"><h3>Archive owner</h3><div class="field"><label>Gmail address</label><input id="sheetEmail" type="email" value="${esc(a.email)}" placeholder="yourname@gmail.com" /></div><div class="field"><label>Apps Script Web App URL</label><input id="sheetEndpoint" value="${esc(a.endpoint)}" placeholder="https://script.google.com/macros/s/…/exec" /></div><button class="primary wide" data-connect-sheets>${a.connected?'Update connection':'Connect archive'}</button><button class="ghost wide" data-export-csv>Download timeline as CSV</button></section><section class="panel"><h3>What gets saved</h3><div class="profile-list"><div class="profile-row"><span>Major achievements</span><b>Automatic</b></div><div class="profile-row"><span>Career milestones</span><b>Automatic</b></div><div class="profile-row"><span>Education & travel</span><b>Automatic</b></div><div class="profile-row"><span>Routine daily actions</span><b>Local only</b></div><div class="profile-row"><span>Last sync</span><b>${a.lastSync||'Not yet synced'}</b></div></div><div class="divider"></div><p class="micro">The endpoint should accept a JSON POST with character, event, date, location and career fields. Until it is configured, every event remains safely in this browser and can be exported as CSV.</p><button class="ghost" style="margin-top:12px" data-test-sheet ${a.connected?'':'disabled'}>Send test event</button></section></div>`; }

function adminHTML(){return `<div class="sheet-banner"><div class="eyebrow">Reality editor</div><h3>Admin access is active</h3><p class="muted micro">Changes apply immediately to this local save.</p></div><div class="admin-grid"><div class="admin-tile"><b>Give money</b><input id="adminMoney" type="number" value="1000000"><button class="tiny-btn" data-admin="money">Apply</button></div><div class="admin-tile"><b>Give age</b><input id="adminAge" type="number" value="1"><button class="tiny-btn" data-admin="age">Apply</button></div><div class="admin-tile"><b>Set every vital</b><input id="adminStats" type="number" value="100" min="0" max="100"><button class="tiny-btn" data-admin="stats">Apply</button></div><div class="admin-tile"><b>Give life points</b><input id="adminPoints" type="number" value="1000"><button class="tiny-btn" data-admin="points">Apply</button></div><div class="admin-tile"><b>Max education</b><p class="micro">Unlock every career requirement.</p><button class="tiny-btn" data-admin="education">Graduate</button></div><div class="admin-tile"><b>Make a relative</b><p class="micro">Adds a new person to the family tree.</p><button class="tiny-btn" data-admin="relative">Create person</button></div></div>`;}

function bindModal(kind){
  $('[data-close]')?.addEventListener('click',closeModal);
  $('.modal-layer')?.addEventListener('click',e=>{if(e.target.classList.contains('modal-layer'))closeModal();});
  $$('[data-tab]').forEach(b=>b.onclick=()=>{modalTab=isNaN(b.dataset.tab)?b.dataset.tab:Number(b.dataset.tab);rerenderModal();});
  $$('[data-activity]').forEach(b=>b.onclick=()=>doActivity(b.dataset.activity));
  $$('[data-job]').forEach(b=>b.onclick=()=>takeJob(b.dataset.job));
  $('[data-work]')?.addEventListener('click',workMonth);
  $('[data-study]')?.addEventListener('click',study);
  $('[data-test]')?.addEventListener('click',takeExam);
  $$('[data-classmate]').forEach(b=>b.onclick=()=>classmateAction(b.dataset.classmate));
  $$('[data-person]').forEach(b=>b.onclick=()=>personAction(b.dataset.person));
  $('[data-meet]')?.addEventListener('click',meetPerson);
  $$('[data-city]').forEach(b=>b.onclick=()=>travel(MAP_CITIES[Number(b.dataset.city)]));
  $('#mapSearch')?.addEventListener('input',mapSearch);
  $$('[data-buy]').forEach(b=>b.onclick=()=>buyItem(b.dataset.buy));
  $('[data-load-market]')?.addEventListener('click',loadMarket);
  $('[data-jump-market]')?.addEventListener('click',e=>{closeModal();openModal('market',e.currentTarget.dataset.jumpMarket);});
  $$('[data-car]').forEach(b=>b.onclick=()=>carAction(b.dataset.car));
  $$('[data-phone-open]').forEach(b=>b.onclick=()=>{closeModal();openModal(b.dataset.phoneOpen);});
  $$('[data-phone-app]').forEach(b=>b.onclick=()=>phoneAction(b.dataset.phoneApp));
  $$('[data-setting]').forEach(b=>b.onclick=()=>toggleSetting(b.dataset.setting));
  $('[data-redeem]')?.addEventListener('click',redeem);
  $('[data-new-life]')?.addEventListener('click',newLife);
  $('[data-connect-sheets]')?.addEventListener('click',connectSheets);
  $('[data-export-csv]')?.addEventListener('click',exportCsv);
  $('[data-test-sheet]')?.addEventListener('click',()=>syncEvent({title:'Connection test',text:'Everlife successfully reached this archive.',major:true},true));
  $$('[data-admin]').forEach(b=>b.onclick=()=>adminAction(b.dataset.admin));
}

function applyEffects(e){ for(const [k,v] of Object.entries(e)){ if(k==='careerXp') state.career.xp+=v; else state.stats[k]=clamp((state.stats[k]||0)+v); } }
function doActivity(key){ let [group,index]=key.split('|'); let a; if(group.startsWith('venue:')){ const venue=group.slice(6); const x=VENUES[venue].actions[Number(index)]; a=[x[0],VENUES[venue].icon,x[1],x[2]]; } else a=ACTIVITY_GROUPS[group][Number(index)]; if(state.money<a[2]) return toast('Not enough money','Choose a free activity or earn more first.'); state.money-=a[2]; applyEffects(a[3]); state.phone.battery=clamp(state.phone.battery-1); addEvent(a[0],`${state.character.first} chose to ${a[0].toLowerCase()}. ${effectText(a[3])}.`,false); afterAction(); rerenderModal(); }
function takeJob(key){ const [t,i]=key.split('|').map(Number),cfg=CAREER_LEVELS[t],sector=CAREER_SECTORS[i]; state.career={title:`${cfg.prefix} ${sector}`,sector,tier:t,salary:cfg.salary+i*17,xp:0}; addEvent('Career breakthrough',`${state.character.name} accepted a role as ${state.career.title}, earning $${fmt(state.career.salary)} per month.`,true); unlock('First Paycheque'); afterAction(); rerenderModal(); }
function workMonth(){ state.money+=state.career.salary; state.career.xp+=12; applyEffects({happiness:-2,hunger:-9,smarts:2}); addEvent('Payday',`A month of work as ${state.career.title} paid $${fmt(state.career.salary)}.`,state.career.xp%60===0); passTime('month',true); rerenderModal(); }
function study(){ applyEffects({smarts:8,happiness:-2,hunger:-5}); state.education.grade=clamp(state.education.grade+2); addEvent('A day of learning',`${state.character.first} attended class and pushed their average to ${Math.round(state.education.grade)}%.`,false); afterAction(); rerenderModal(); }
function takeExam(){ const questions=[['What is 12 × 8?','96'],['Which gas do plants absorb?','carbon dioxide'],['What is the capital of Japan?','tokyo'],['Who wrote Romeo and Juliet?','shakespeare'],['What is H₂O commonly called?','water']]; let score=0; questions.forEach(q=>{ const ans=prompt(q[0]); if(ans?.trim().toLowerCase()===q[1]) score++; }); const grade=score*20; state.education.grade=Math.round((state.education.grade+grade)/2); if(grade>=60) applyEffects({smarts:5,happiness:4}); else applyEffects({happiness:-3}); addEvent(grade>=60?'Exam passed':'Exam completed',`${state.character.first} scored ${grade}% on a five-subject assessment.`,grade>=80); afterAction(); rerenderModal(); }
function classmateAction(key){ const [id,act]=key.split('|'),p=state.classmates.find(x=>x.id==id); if(act==='talk'){p.friendship=clamp(p.friendship+7);p.memory=`You shared a ${pick(['funny','honest','surprising','thoughtful'])} conversation in class.`;applyEffects({social:4,happiness:3});}else{p.friendship=clamp(p.friendship+5);p.memory='You prepared for an exam together.';applyEffects({smarts:5,social:2});} addEvent(`Time with ${p.name}`,p.memory,false);afterAction();rerenderModal(); }
function personAction(key){ const [id,act]=key.split('|'),p=state.relationships.find(x=>x.id==id); if(act==='gift'){if(state.money<25)return toast('Not enough money','A thoughtful call is free.');state.money-=25;p.bond=clamp(p.bond+8);applyEffects({happiness:3,social:5});}else{p.bond=clamp(p.bond+5);applyEffects({social:4,happiness:2});}addEvent(`Connected with ${p.name}`,act==='gift'?'You sent a thoughtful gift.':'You caught up over a long call.',false);afterAction();rerenderModal();}
function meetPerson(){ const first=pick(['Zara','Eli','Ava','Sibusiso','Maya','Leo','Naledi','Theo']),last=pick(['Naidoo','Smith','Diallo','Chen','Meyer','Dube']);state.relationships.push({id:Date.now(),name:`${first} ${last}`,role:pick(['Friend','Friend','Partner']),age:Math.max(18,state.character.age+Math.floor(Math.random()*7)-3),bond:34,emoji:first[0]});addEvent('A new connection',`${state.character.first} met ${first} in ${state.character.city}.`,false);if(state.relationships.length>=5)unlock('Found Family');afterAction();rerenderModal();}
function mapSearch(e){ const q=e.target.value.trim().toLowerCase();mapSearchResults=[];if(q.length>=2){for(const country of ALL_WORLD_COUNTRIES){if(country.name.toLowerCase().includes(q))for(const city of country.cities.slice(0,4)){mapSearchResults.push({name:city,country:country.name});if(mapSearchResults.length>=18)break;}if(mapSearchResults.length>=18)break;for(const city of country.cities){if(city.toLowerCase().includes(q)){mapSearchResults.push({name:city,country:country.name});if(mapSearchResults.length>=18)break;}}if(mapSearchResults.length>=18)break;}}$('#mapResult').innerHTML=q.length>=2?(mapSearchResults.map((c,i)=>`<button class="tiny-btn" style="margin:6px 4px 0 0" data-search-city="${i}">${esc(c.name)} · ${esc(c.country)}</button>`).join('')||'No city found in 134,000 destinations.'):'Type at least two letters to search every city.';$$('[data-search-city]').forEach(b=>b.onclick=()=>travel(mapSearchResults[Number(b.dataset.searchCity)])); }
function travel(city){ const cost=city.country===state.character.country?80:650;if(state.money<cost)return toast('Travel costs $'+cost,'Earn more or choose a closer destination.'); if(!confirm(`Travel to ${city.name}, ${city.country} for $${cost}?`))return;state.money-=cost;state.character.city=city.name;state.character.country=city.country;const country=ALL_WORLD_COUNTRIES.find(item=>item.name===city.country);if(country){state.character.countryCode=country.code;state.character.flag=country.flag;state.character.currency=country.currency;state.character.continent=country.continent;}if(!state.visited.includes(city.name))state.visited.push(city.name);applyEffects({happiness:12,hunger:-8,social:4});addEvent('Arrived in '+city.name,`${state.character.name} travelled to ${city.country} and began exploring.`,true);if(state.visited.length>=3)unlock('World Citizen');afterAction();rerenderModal();}
function buyItem(key){const [cat,i,p]=key.split('|'),price=Number(p);if(state.money<price)return toast('Not enough money',`You need $${fmt(price-state.money)} more.`);const base=MARKET[cat][Number(i)%MARKET[cat].length],name=`${['Classic','Studio','Nova','Heritage','Ultra','Local','Apex'][Math.floor(Number(i)/MARKET[cat].length)%7]} ${base}`;state.money-=price;const item={name,category:cat,value:price};state.inventory.push(item);if(cat==='Food'){applyEffects({hunger:22,happiness:3});}if(cat==='Vehicles'){state.vehicles.push({name,value:price,condition:100,distance:0});}if(cat==='Apparel')applyEffects({happiness:4,social:2});if(state.inventory.length>=10)unlock('Collector');addEvent('Bought '+name,`${state.character.first} added a new ${cat.toLowerCase()} item to their life.`,price>100000);afterAction();rerenderModal();}
function loadMarket(){ const grid=$('#marketGrid'),count=grid.children.length;grid.insertAdjacentHTML('beforeend',marketItems(modalTab||'Food',count,24));$$('[data-buy]').slice(count).forEach(b=>b.onclick=()=>buyItem(b.dataset.buy));sfx('click'); }
function carAction(key){const [idx,act]=key.split('|'),car=state.vehicles[idx];if(act==='drive'){car.distance+=Math.floor(12+Math.random()*90);car.condition=clamp(car.condition-2);applyEffects({happiness:7,hunger:-3});addEvent('Road trip',`${state.character.first} took the ${car.name} out for a drive.`,false);}if(act==='clean'){if(state.money<20)return toast('Not enough money','A car wash costs $20.');state.money-=20;car.condition=clamp(car.condition+8);toast('Freshly detailed',`${car.name} is looking sharp.`);}if(act==='sell'){if(!confirm(`Sell ${car.name} for $${fmt(car.value*.65)}?`))return;state.money+=car.value*.65;state.vehicles.splice(idx,1);state.inventory=state.inventory.filter(x=>x.name!==car.name);addEvent('Vehicle sold',`${car.name} left the garage.`,false);}afterAction();rerenderModal();}
function phoneAction(name){state.phone.battery=clamp(state.phone.battery-2);const messages={Messages:'No unread messages. Try calling someone from Relationships.', 'My Bank':`Available balance: $${fmt(state.money)}.`,Camera:'A golden-hour photo was added to your memories.', 'Chat MTP':'Chat MTP is in offline life-coach mode: protect your health, invest in skills, and call your family.', 'Play Store':'The LifeOS game catalogue is updating. Three puzzle games are installed.',Dating:'Three people nearby share your interests.',Gallery:'Your gallery holds moments from '+state.visited.join(', '),Calendar:`Today is ${monthName(state.calendar.month)} ${state.calendar.day}, ${state.calendar.year}.`,Health:`Health ${state.stats.health}% · Hunger ${state.stats.hunger}%`};toast(name,messages[name]||'App opened.');save();}
function toggleSetting(key){state.settings[key]=!state.settings[key];save();rerenderModal();}
function redeem(){ const code=$('#redeemInput').value.trim().toLowerCase();if(!code)return;if(state.redeemed.includes(code))return toast('Code already used','Each code can be redeemed once per life.');if(code==='admin123'){state.admin=true;state.points+=500_000_000_000;state.redeemed.push(code);addEvent('Reality editor unlocked','The admin panel appeared and 500B life points were added.',true);toast('Admin unlocked','500B points added. The Admin Panel is now in the sidebar.');}else if(code==='guest666'){state.points+=1000;state.redeemed.push(code);toast('Guest gift','1,000 life points added.');}else if(code==='starter'){state.money+=500;state.redeemed.push(code);toast('Starter gift','$500 added.');}else return toast('Unknown code','That code does not exist in this build.');afterAction();rerenderModal();}
function newLife(){if(!confirm('Start a completely new life? Your current local save will be replaced. Export your timeline first if you want to keep it.'))return;storageRemove(STORAGE_KEY);state=null;closeModal();render();}
function connectSheets(){ const email=$('#sheetEmail').value.trim(),endpoint=$('#sheetEndpoint').value.trim();if(email&&!/^[^@]+@gmail\.com$/i.test(email))return toast('Use a Gmail address','This archive is designed for one Google account.');if(endpoint&&!/^https:\/\/script\.google\.com\/macros\/s\//.test(endpoint))return toast('Endpoint not recognised','Use the deployed Google Apps Script web app URL ending in /exec.');state.archive={...state.archive,email,endpoint,connected:Boolean(email&&endpoint)};storageSet(ARCHIVE_KEY,JSON.stringify(state.archive));save();toast(state.archive.connected?'Archive connected':'Archive owner saved',state.archive.connected?'Major events from every new character will now be sent automatically.':'Add an Apps Script endpoint when you are ready for automatic sync.');rerenderModal();}
async function syncEvent(event,test=false){if(!state.archive.connected||!state.archive.endpoint)return;const payload={owner:state.archive.email,character:state.character.name,event:event.title,details:event.text,date:`${state.calendar.year}-${String(state.calendar.month).padStart(2,'0')}-${String(state.calendar.day).padStart(2,'0')}`,age:state.character.age,location:`${state.character.city}, ${state.character.country}`,career:state.career.title,test};try{await fetch(state.archive.endpoint,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify(payload)});state.archive.lastSync=new Date().toLocaleString();save();if(test)toast('Test sent','Check the connected Google Sheet for a new row.');}catch(e){toast('Sync could not reach Google','The event is still saved locally. Check your endpoint deployment.');}}
function exportCsv(){const rows=[['Character','Event','Details','Recorded date','Age','Location','Career'],...state.events.slice().reverse().map(e=>[state.character.name,e.title,e.text,e.date,e.age??state.character.age,e.location||`${state.character.city}, ${state.character.country}`,e.career||state.career.title])];const csv=rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`everlife-${state.character.first.toLowerCase()}-timeline.csv`;a.click();URL.revokeObjectURL(url);toast('Timeline exported','Your CSV is ready for Google Sheets.');}
function adminAction(type){if(type==='money')state.money+=Number($('#adminMoney').value)||0;if(type==='age'){const n=Number($('#adminAge').value)||0;state.character.age=Math.max(0,state.character.age+n);}if(type==='stats'){const v=clamp(Number($('#adminStats').value)||0);Object.keys(state.stats).forEach(k=>state.stats[k]=v);}if(type==='points')state.points+=Number($('#adminPoints').value)||0;if(type==='education'){state.education={level:5,name:'Doctorate',grade:100};state.stats.smarts=100;}if(type==='relative'){const id=Date.now(),first=pick(['Nova','Liam','Imani','Alex','River']);state.relationships.push({id,name:`${first} ${state.character.last}`,role:pick(['Sibling','Cousin','Child']),age:Math.max(0,state.character.age-18),bond:70,emoji:first[0]});}addEvent('Admin change applied',`The ${type} control changed this life.`,false);afterAction();rerenderModal();}

function passTime(unit,quiet=false){
  if(!state.alive)return toast('This life has ended','Start a new life from phone settings.');
  if(unit==='day'){state.calendar.day++;applyEffects({hunger:-4,health:state.stats.hunger<20?-3:0,happiness:-.4});if(state.calendar.day>30){state.calendar.day=1;state.calendar.month++;}}
  else {state.calendar.month++;applyEffects({hunger:-13,health:state.stats.hunger<25?-7:-1,happiness:-1});state.money-=Math.min(state.money,Math.round(150+state.character.age*2));}
  if(state.calendar.month>12){state.calendar.month=1;state.calendar.year++;ageUp();}
  if(state.stats.hunger<=0){state.alive=false;state.stats.health=0;addEvent('Life ended',`${state.character.name} died from prolonged hunger at age ${state.character.age}.`,true);}
  else if(!quiet && Math.random()<.34)randomEvent();
  afterAction();renderGame();if(!quiet)sfx('time');
}
function ageUp(){state.character.age++;state.relationships.forEach(r=>r.age++);state.classmates.forEach(p=>p.friendship=clamp(p.friendship+Math.floor(Math.random()*7)-2));addEvent(`Turned ${state.character.age}`,`${state.character.name} begins another year with ${state.events.length} memories behind them. One million new market variations are now available.`,true);if(state.character.age===21&&state.education.level<2){state.education={level:2,name:'Undergraduate Studies',grade:state.education.grade};addEvent('University chapter','A new education tier is now open.',true);}if(state.character.age>=100)unlock('Century');}
function randomEvent(){const events=[['An unexpected compliment','A stranger noticed your energy today.',{happiness:5,social:2}],['Rain changed the plan','You slowed down and listened to the weather.',{happiness:2}],['A difficult morning','Nothing went quite to plan, but you kept moving.',{happiness:-4,health:-1}],['A brilliant idea','A new possibility arrived fully formed.',{smarts:3,happiness:3}],['Neighbourhood festival','Music and food filled the street.',{social:6,happiness:5,hunger:5}]],e=pick(events);applyEffects(e[2]);addEvent(e[0],e[1],false);}
function addEvent(title,text,major=false){const e={date:`${monthName(state.calendar.month).slice(0,3)} ${state.calendar.day}, ${state.calendar.year}`,title,text,major,age:state.character.age,location:`${state.character.city}, ${state.character.country}`,career:state.career.title};state.events.unshift(e);if(state.events.length>250)state.events.length=250;if(major)syncEvent(e);}
function unlock(name){if(state.achievements.includes(name))return;state.achievements.push(name);state.points+=250;toast('Milestone unlocked',`${name} · +250 life points`);}
function checkAchievements(){if(state.stats.smarts>=90)unlock('Deep Thinker');if(state.money>=1e9)unlock('Billionaire');}
function afterAction(){checkAchievements();save();sfx('click');}
function toast(title,copy=''){const host=$('#toastHost'),el=document.createElement('div');el.className='toast';el.innerHTML=`<b>${esc(title)}</b>${esc(copy)}`;host.append(el);setTimeout(()=>el.remove(),3800);}
function sfx(type){if(!state?.settings?.sound)return;try{const C=window.AudioContext||window.webkitAudioContext,ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=type==='start'?620:type==='time'?410:520;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);o.start();o.stop(ctx.currentTime+.13);}catch{}}

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.modal-layer'))closeModal();});
try {
  render();
} catch (error) {
  console.error('Everlife failed to start', error);
  window.__everlifeBootError?.(error.message);
}
